(4240706, 611707, 15711, '<td valign="top">Stunning.  This has <img alt="'' . substr(''//www.dpchallenge.com/images/user_icon/21_F.gif'', strrpos(''//www.dpchallenge.com/images/user_icon/21_F.gif'', ''/'') + 1) . ''" border="0" src="//www.dpchallenge.com/images/user_icon/21_F.gif"/> <a href="//www.dpchallenge.com/profile.php?USER_ID=5112" rel="nofollow" target="_blank">ursula</a> written all over it~~</td>', 'Stunning.  This has  ursula written all over it~~', '2007-11-12 10:03:23.000000', NULL, 1),
(4240710, 611559, 15711, '<td valign="top">Nicely done.  The duo really lets us concentrate on all of the various shapes.  In color, it would probably be too busy, but in duo, the mimicked shapes work well. The arches of the bridge are even the same shape as the boats in reverse! Nice perspective.</td>', 'Nicely done.  The duo really lets us concentrate on all of the various shapes.  In color, it would probably be too busy, but in duo, the mimicked shapes work well. The arches of the bridge are even the same shape as the boats in reverse! Nice perspective.', '2007-11-12 10:05:09.000000', NULL, 1),
(4240714, 609675, 15711, '<td valign="top">Lovely vista.</td>', 'Lovely vista.', '2007-11-12 10:06:42.000000', NULL, 1),
(4240718, 610409, 15711, '<td valign="top">Love the editing and use of neg space.  If I were to critique anything, I''d tilt it about two degrees to the right, as it has an uneven quality, although that may have been your intent. Love the tones.</td>', 'Love the editing and use of neg space.  If I were to critique anything, I''d tilt it about two degrees to the right, as it has an uneven quality, although that may have been your intent. Love the tones.', '2007-11-12 10:09:04.000000', NULL, 1),
(4240729, 611128, 15711, '<td valign="top">Love the line and the tones but I''m not too sure about the red.  I think a blue/gray or maybe a warm BW would suit it better.  Bravo on the comp and focus though. Great leading line.</td>', 'Love the line and the tones but I''m not too sure about the red.  I think a blue/gray or maybe a warm BW would suit it better.  Bravo on the comp and focus though. Great leading line.', '2007-11-12 10:13:35.000000', NULL, 1),
(4240731, 611825, 76198, '<td valign="top">Love it.</td>', 'Love it.', '2007-11-12 10:14:29.000000', NULL, 1),
(4240732, 611575, 1024, '<td valign="top">Wonderful title, great colors.</td>', 'Wonderful title, great colors.', '2007-11-12 10:14:45.000000', NULL, 1),
(4240734, 610415, 76198, '<td valign="top">This isn''t a DPC friendly image, but I really like it.</td>', 'This isn''t a DPC friendly image, but I really like it.', '2007-11-12 10:16:12.000000', NULL, 1),
(4240742, 612272, 674, '<td valign="top">nice reflections, nice leadin lines but no real focal point 6</td>', 'nice reflections, nice leadin lines but no real focal point 6', '2007-11-12 10:18:23.000000', NULL, 1),
(4240754, 611734, 15711, '<td valign="top">Great lighting.</td>', 'Great lighting.', '2007-11-12 10:22:36.000000', NULL, 1),
