(4240769, 611401, 15711, '<td valign="top">OH wow. Could have been used for "topless" too. This has <img alt="'' . substr(''//www.dpchallenge.com/images/user_icon/21.gif'', strrpos(''//www.dpchallenge.com/images/user_icon/21.gif'', ''/'') + 1) . ''" border="0" src="//www.dpchallenge.com/images/user_icon/21.gif"/> <a href="//www.dpchallenge.com/profile.php?USER_ID=60915" rel="nofollow" target="_blank">nixter</a> written all over it.</td>', 'OH wow. Could have been used for "topless" too. This has  nixter written all over it.', '2007-11-12 10:35:04.000000', NULL, 1),
(4240775, 609809, 15711, '<td valign="top">I like the light.  Nice simplicity. Not many still lifes, eh?</td>', 'I like the light.  Nice simplicity. Not many still lifes, eh?', '2007-11-12 10:36:45.000000', NULL, 1),
(4240778, 611520, 15711, '<td valign="top">Love the dim lighting.  very cool.</td>', 'Love the dim lighting.  very cool.', '2007-11-12 10:38:06.000000', NULL, 1),
(4240785, 611534, 15711, '<td valign="top">Simple and lovely.  My kind of image. I might''ve burned a touch on the leaf to really pop out the veins, but otherwise - awesome.</td>', 'Simple and lovely.  My kind of image. I might''ve burned a touch on the leaf to really pop out the veins, but otherwise - awesome.', '2007-11-12 10:46:04.000000', NULL, 1),
(4240788, 611825, 15711, '<td valign="top">Fun. Love the motion blur.</td>', 'Fun. Love the motion blur.', '2007-11-12 10:47:49.000000', NULL, 1),
(4240798, 611540, 15711, '<td valign="top">Oh my.  That is EXCELLENT.  Baaaaah. 8</td>', 'Oh my.  That is EXCELLENT.  Baaaaah. 8', '2007-11-12 10:53:34.000000', NULL, 1),
(4240799, 610242, 15711, '<td valign="top">I could do without the woman.  Man, the sky is awesome. Great tonal range. 7</td>', 'I could do without the woman.  Man, the sky is awesome. Great tonal range. 7', '2007-11-12 10:54:41.000000', NULL, 1),
(4240801, 611771, 66193, '<td valign="top">I like the use of shallow DOF here.</td>', 'I like the use of shallow DOF here.', '2007-11-12 10:56:26.000000', NULL, 1),
(4240804, 611770, 15711, '<td valign="top">Was it Anne Geddes that started this idea? I think with the cool tones, it has a kind of sinister feel, not warm and fuzzy. I would like it much better with a sepia, or gray/brown duotone.</td>', 'Was it Anne Geddes that started this idea? I think with the cool tones, it has a kind of sinister feel, not warm and fuzzy. I would like it much better with a sepia, or gray/brown duotone.', '2007-11-12 10:59:14.000000', NULL, 1),
(4240805, 612272, 66193, '<td valign="top">I don''t care for the choice of tone here.  green doesn''t seem to work well with this image.  I do like the reflections.</td>', 'I don''t care for the choice of tone here.  green doesn''t seem to work well with this image.  I do like the reflections.', '2007-11-12 10:59:15.000000', NULL, 1),
(4240806, 612246, 15711, '<td valign="top">NICE.  Very crisp.  The smooth water and clouds are like velvet. Nice lines. too. Well done.</td>', 'NICE.  Very crisp.  The smooth water and clouds are like velvet. Nice lines. too. Well done.', '2007-11-12 10:59:41.000000', NULL, 1),
(4240810, 611207, 15711, '<td valign="top">Love the eyes. The lighting is good but has a flat feel if that makes sense at all. Great use of neg. space. Love the hair hanging over on the left. 7</td>', 'Love the eyes. The lighting is good but has a flat feel if that makes sense at all. Great use of neg. space. Love the hair hanging over on the left. 7', '2007-11-12 11:01:05.000000', NULL, 1),
(4240811, 610242, 66193, '<td valign="top">absolutely love it!  contrasts are spot on, and very good use of dodge and burn; excellent manipulation of light.</td>', 'absolutely love it!  contrasts are spot on, and very good use of dodge and burn; excellent manipulation of light.', '2007-11-12 11:01:16.000000', NULL, 1),
(4240813, 610543, 66193, '<td valign="top">very nice high contrast image.  the symmetry works well here.</td>', 'very nice high contrast image.  the symmetry works well here.', '2007-11-12 11:02:48.000000', NULL, 1),
(4240814, 611851, 15711, '<td valign="top">Wonderful light and shadow ratio.  Her eyes and expression - AWESOME</td>', 'Wonderful light and shadow ratio.  Her eyes and expression - AWESOME', '2007-11-12 11:03:01.000000', NULL, 1),
(4240815, 610417, 66193, '<td valign="top">focus looks just a tad off (his nose is in focus, not his eyes).  Nice image overall.</td>', 'focus looks just a tad off (his nose is in focus, not his eyes).  Nice image overall.', '2007-11-12 11:03:21.000000', NULL, 1),
(4240817, 611756, 80908, '<td valign="top">lovely detail and focus - I would have been tempted to rotate for a little more diagonal angle to lead the eye in from the corner maybe.</td>', 'lovely detail and focus - I would have been tempted to rotate for a little more diagonal angle to lead the eye in from the corner maybe.', '2007-11-12 11:05:05.000000', NULL, 1),
(4240819, 611722, 15711, '<td valign="top">The eyes are terrific but I feel that the rest of the tones leave us wanting.  I would play with contrast, levels and curves, but that''s just me.  She has that sad urchin expression.</td>', 'The eyes are terrific but I feel that the rest of the tones leave us wanting.  I would play with contrast, levels and curves, but that''s just me.  She has that sad urchin expression.', '2007-11-12 11:05:36.000000', NULL, 1),
(4240821, 611834, 80908, '<td valign="top">Fun photo!</td>', 'Fun photo!', '2007-11-12 11:06:29.000000', NULL, 1),
(4240826, 611607, 80908, '<td valign="top">Could do with a little more contrast or shadow to make the parts of the photo stand out.</td>', 'Could do with a little more contrast or shadow to make the parts of the photo stand out.', '2007-11-12 11:07:32.000000', NULL, 1),
(4240828, 609594, 80908, '<td valign="top">Great, stark photo. Like it.</td>', 'Great, stark photo. Like it.', '2007-11-12 11:08:01.000000', NULL, 1),
(4240835, 611742, 80908, '<td valign="top">Nice textures, perhaps more contrast would have picked it out better?</td>', 'Nice textures, perhaps more contrast would have picked it out better?', '2007-11-12 11:09:21.000000', NULL, 1),
(4240836, 610882, 69102, '<td valign="top">very nice. having grown up in western washington, this almost doesn''t even seem like a duotone.</td>', 'very nice. having grown up in western washington, this almost doesn''t even seem like a duotone.', '2007-11-12 11:10:05.000000', NULL, 1),
(4240838, 611557, 15711, '<td valign="top">I''m a sucker for a cool title.  Great idea.  A touch tight in the crop but the lighting and tones - spot on.</td>', 'I''m a sucker for a cool title.  Great idea.  A touch tight in the crop but the lighting and tones - spot on.', '2007-11-12 11:10:29.000000', NULL, 1),
(4240843, 611733, 80908, '<td valign="top">Not convinced that this is duotone.</td>', 'Not convinced that this is duotone.', '2007-11-12 11:11:18.000000', NULL, 1),
(4240846, 610417, 80908, '<td valign="top">Great shot. Nothing more to say about that - best so far!</td>', 'Great shot. Nothing more to say about that - best so far!', '2007-11-12 11:12:15.000000', NULL, 1);
