(4240849, 611463, 80908, '<td valign="top">DNMC - perhaps the fore-bokeh challenge?</td>', 'DNMC - perhaps the fore-bokeh challenge?', '2007-11-12 11:13:04.000000', NULL, 1),
(4240852, 611022, 80908, '<td valign="top">Interesting use of noise - but too much seems to be lost in it.</td>', 'Interesting use of noise - but too much seems to be lost in it.', '2007-11-12 11:14:16.000000', NULL, 1),
(4240856, 609675, 80908, '<td valign="top">Very atmospheric - possibly could have cropped bottom inch or so but not marking it any lower because of that. Nice work!</td>', 'Very atmospheric - possibly could have cropped bottom inch or so but not marking it any lower because of that. Nice work!', '2007-11-12 11:16:10.000000', NULL, 1),
(4240859, 611403, 80908, '<td valign="top">Not sure why, but this definitely caught my attention.  Possibly the way that the light bounces around it? Really nice use of B/W or duotone.</td>', 'Not sure why, but this definitely caught my attention.  Possibly the way that the light bounces around it? Really nice use of B/W or duotone.', '2007-11-12 11:18:17.000000', NULL, 1),
(4240860, 609982, 66193, '<td valign="top">lovely atmosphere.  a slightly tighter crop on the bottom (just below the dogs legs) would make for a stronger composition.  8</td>', 'lovely atmosphere.  a slightly tighter crop on the bottom (just below the dogs legs) would make for a stronger composition.  8', '2007-11-12 11:18:47.000000', NULL, 1),
(4240863, 610934, 80908, '<td valign="top">Classic. Almost too dark at the top, but that may be my screen. Best so far.</td>', 'Classic. Almost too dark at the top, but that may be my screen. Best so far.', '2007-11-12 11:19:43.000000', NULL, 1),
