INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4241562, 611460, 7778, '<td valign="top">Energy/Range/Story: 9/8/8 <br/>Composition/perspective/manner: 8/7/8 <br/>Aesthetics/Technical: 9/9 <br/>Presentation: 8 <br/>Total: 8.2 <br/>Vote: 8<br/> <br/>Remarks: The company of an image like this is as venerable as it is well occupied, which opens it for much "racy" competition, making it difficult to award 10s. Another consideration would be the fact that the photograph itself is an "hommage" to its subject - and an excellent one at that. What is interesting here, that all these aspects compliment one another seamlessly and without attracting any undue attention to anything but the sum of their parts - in what I would call a "great photograph and accomplishment".</td>', 'Energy/Range/Story: 9/8/8 Composition/perspective/manner: 8/7/8 Aesthetics/Technical: 9/9 Presentation: 8 Total: 8.2 Vote: 8 Remarks: The company of an image like this is as venerable as it is well occupied, which opens it for much "racy" competition, making it difficult to award 10s. Another consideration would be the fact that the photograph itself is an "hommage" to its subject - and an excellent one at that. What is interesting here, that all these aspects compliment one another seamlessly and without attracting any undue attention to anything but the sum of their parts - in what I would call a "great photograph and accomplishment".', '2007-11-12 15:38:16.000000', NULL, 1),
(4241573, 609809, 27514, '<td valign="top">I love this image had you thought about cropping in on the left, the info there isn''t doing much for the image and it would take away the blown out whites.<br/> <br/>overall nice image. 8</td>', 'I love this image had you thought about cropping in on the left, the info there isn''t doing much for the image and it would take away the blown out whites. overall nice image. 8', '2007-11-12 15:48:42.000000', NULL, 1),
