(4245744, 609907, 55494, '<td valign="top">Beautiful colors and texture! This is an amazing shot.</td>', 'Beautiful colors and texture! This is an amazing shot.', '2007-11-14 03:04:56.000000', NULL, 1),
(4245753, 611207, 69368, '<td valign="top">oh! this is sooo beautiful. Her expression is full of life. the tones work very well. Very well done! I''m sure, this will be in the Top 3! - Good luck!</td>', 'oh! this is sooo beautiful. Her expression is full of life. the tones work very well. Very well done! I''m sure, this will be in the Top 3! - Good luck!', '2007-11-14 03:13:02.000000', NULL, 1),
(4246007, 611556, 6999, '<td valign="top">Enjoy the massive contrast here; makes one wonder whether taking it further still, to white-out the face almost completely rather than only in certain areas might have further emphasised the fundamental black and white.</td>', 'Enjoy the massive contrast here; makes one wonder whether taking it further still, to white-out the face almost completely rather than only in certain areas might have further emphasised the fundamental black and white.', '2007-11-14 07:45:45.000000', NULL, 1),
(4246014, 611746, 6999, '<td valign="top">A fine image. A pity you haven''t re-sized to the maximum allowed dimensions - one suspects, seeing as its 480 tall, that you might have misunderstood the allowance. The graininess is fabulous, the simplicity exemplary; and the tonality matches the mood - some, I suspect, will tell you that you need to use more of teh available dynamic range - this image has no areas anywhere near white - but I think you have made the right choice in keeping to a more muted palette. Enjoyable mysterious, too.</td>', 'A fine image. A pity you haven''t re-sized to the maximum allowed dimensions - one suspects, seeing as its 480 tall, that you might have misunderstood the allowance. The graininess is fabulous, the simplicity exemplary; and the tonality matches the mood - some, I suspect, will tell you that you need to use more of teh available dynamic range - this image has no areas anywhere near white - but I think you have made the right choice in keeping to a more muted palette. Enjoyable mysterious, too.', '2007-11-14 07:48:19.000000', NULL, 1),
(4246034, 610703, 86629, '<td valign="top">nice shot</td>', 'nice shot', '2007-11-14 08:00:32.000000', NULL, 1),
(4246064, 611722, 56978, '<td valign="top">excellent eyes but I feel the rest of the photo could have more contrast</td>', 'excellent eyes but I feel the rest of the photo could have more contrast', '2007-11-14 08:16:13.000000', NULL, 1),
(4246162, 611704, 81382, '<td valign="top">The blue duotone hue is quite dominant. Better tonal seperation between the sky (i.e. blow the sky out to near white) would have made the image less blue overall and more clearly define the structure.</td>', 'The blue duotone hue is quite dominant. Better tonal seperation between the sky (i.e. blow the sky out to near white) would have made the image less blue overall and more clearly define the structure.', '2007-11-14 08:49:33.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4246172, 610415, 81382, '<td valign="top">Seems quite "gritty" which I quite like. The boys face is an area of interest which unfortunately has lost a lot of detail as it is clipped at  the top end. Good timing though in getting this shot, the still life people have the luxury of being able to easily repeat the image for the perfect capture but hopefully voters will understand this is not the case here and should award higher than normal marks accordingly</td>', 'Seems quite "gritty" which I quite like. The boys face is an area of interest which unfortunately has lost a lot of detail as it is clipped at  the top end. Good timing though in getting this shot, the still life people have the luxury of being able to easily repeat the image for the perfect capture but hopefully voters will understand this is not the case here and should award higher than normal marks accordingly', '2007-11-14 08:52:35.000000', NULL, 1),
(4246180, 611581, 81382, '<td valign="top">Very crisp and good tonal range. Burning out areas of the sky (car tv show style) to be darker than even the top of the hills would have made this very dramatic</td>', 'Very crisp and good tonal range. Burning out areas of the sky (car tv show style) to be darker than even the top of the hills would have made this very dramatic', '2007-11-14 08:54:54.000000', NULL, 1),
(4246192, 610899, 81382, '<td valign="top">Free falling water, either requiring a fast shutter speed for freeze frame or a very long one for "ghost" effects. This is somewhere towards the freeze frame but could be sharper. Duotone hue is quite dominant, I''m tending to favour the more subtle ones</td>', 'Free falling water, either requiring a fast shutter speed for freeze frame or a very long one for "ghost" effects. This is somewhere towards the freeze frame but could be sharper. Duotone hue is quite dominant, I''m tending to favour the more subtle ones', '2007-11-14 09:01:16.000000', NULL, 1),
(4246198, 611375, 81382, '<td valign="top">Noisy, blown out, seems quite pixelated. I see red and blue hues to not sure if this strictly counts as duotone, certainly I have not seen any other tritone entries yet during my voting. Quite nicely composed though, your main subject, the log, is positioned roughly a third to the left</td>', 'Noisy, blown out, seems quite pixelated. I see red and blue hues to not sure if this strictly counts as duotone, certainly I have not seen any other tritone entries yet during my voting. Quite nicely composed though, your main subject, the log, is positioned roughly a third to the left', '2007-11-14 09:04:23.000000', NULL, 1),
(4246215, 611731, 85959, '<td valign="top">I really like it!!</td>', 'I really like it!!', '2007-11-14 09:14:13.000000', NULL, 1),
(4246258, 610242, 57886, '<td valign="top">I really like the surroundings in this picture and the pp you did... Am not sure about the girl there, but hey... Nice pic..</td>', 'I really like the surroundings in this picture and the pp you did... Am not sure about the girl there, but hey... Nice pic..', '2007-11-14 09:33:51.000000', NULL, 1),
(4246259, 610359, 78886, '<td valign="top">Perfect</td>', 'Perfect', '2007-11-14 09:34:03.000000', NULL, 1),
