(4249187, 611747, 66348, '<td valign="top">Great expression and composition. Perhaps a boost in contrast would make this a stronger image IMO. Nice work.</td>', 'Great expression and composition. Perhaps a boost in contrast would make this a stronger image IMO. Nice work.', '2007-11-15 11:44:21.000000', NULL, 1),
(4249190, 611088, 5112, '<td valign="top">Good idea for a duotone challenge, to make an image that looks "old".  It has a bit of a "muddied" look to it though, not sure why.  As a composition it is good, but there really isn''t that much of interest for the casual viewer.  In other words, it doens''t "WOW" the DPC audience.  Hope that helps.  -6</td>', 'Good idea for a duotone challenge, to make an image that looks "old".  It has a bit of a "muddied" look to it though, not sure why.  As a composition it is good, but there really isn''t that much of interest for the casual viewer.  In other words, it doens''t "WOW" the DPC audience.  Hope that helps.  -6', '2007-11-15 11:46:01.000000', NULL, 1),
(4249192, 609317, 66348, '<td valign="top">Great composition and B&amp;W conversion.</td>', 'Great composition and B&W conversion.', '2007-11-15 11:46:21.000000', NULL, 1),
