(4250638, 611533, 62318, '<td valign="top">Interesting concept. I like the light trail effect in the stars and the emphasize on Orion. Is that a phone cord?</td>', 'Interesting concept. I like the light trail effect in the stars and the emphasize on Orion. Is that a phone cord?', '2007-11-15 21:56:27.000000', NULL, 1),
(4250639, 611435, 62318, '<td valign="top">I like the tone vaules you used here. It gives the shot an almost creepy feelings. The textured hair really adds interest to the otherwise clean organized lines. Not sure if I like the bar(?) on the right, but it does give some additional depth.</td>', 'I like the tone vaules you used here. It gives the shot an almost creepy feelings. The textured hair really adds interest to the otherwise clean organized lines. Not sure if I like the bar(?) on the right, but it does give some additional depth.', '2007-11-15 21:57:40.000000', NULL, 1),
(4250640, 612269, 62318, '<td valign="top">Nice textures are created in the rust and the different forms of paint. I might have preferred a slight crop off the left to not include the trees. While I see you wanted to include the handlebar I think the trees take away more from the photo than the handle bar gives. I do like the overall composition of the photo though. From the cut of tire, and the repeating round circles. Good lines.</td>', 'Nice textures are created in the rust and the different forms of paint. I might have preferred a slight crop off the left to not include the trees. While I see you wanted to include the handlebar I think the trees take away more from the photo than the handle bar gives. I do like the overall composition of the photo though. From the cut of tire, and the repeating round circles. Good lines.', '2007-11-15 21:59:43.000000', NULL, 1),
(4250641, 610592, 62318, '<td valign="top">Not sure exactly what I am looking at, but I like the effect. Feels like another planet. The emitting forms of light and the competing darkness works well. A slightly sharper focus might have improved the image a bit, but it is a wonderful abstract the way it is.</td>', 'Not sure exactly what I am looking at, but I like the effect. Feels like another planet. The emitting forms of light and the competing darkness works well. A slightly sharper focus might have improved the image a bit, but it is a wonderful abstract the way it is.', '2007-11-15 22:00:52.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4250643, 611629, 62318, '<td valign="top">Very nice beach/infrared scene. I like the textures you managed to create. I might have preferred the two individuals walking into the frame facing the camera, but I do like the moment  you caught with the father looking down at the son.</td>', 'Very nice beach/infrared scene. I like the textures you managed to create. I might have preferred the two individuals walking into the frame facing the camera, but I do like the moment  you caught with the father looking down at the son.', '2007-11-15 22:01:54.000000', NULL, 1),
(4250647, 611675, 62318, '<td valign="top">I like the competing textures. I think it works well. It might have worked even better if this was closer, as I think the negative space on the left deters from the image a bit.</td>', 'I like the competing textures. I think it works well. It might have worked even better if this was closer, as I think the negative space on the left deters from the image a bit.', '2007-11-15 22:02:49.000000', NULL, 1),
(4250651, 611368, 62318, '<td valign="top">I like the pose and a terrific smile. Interesting choice in color for your duo tone. Gives the image more of a fun happy vibe which is expressed in the emotion of the individual. Might be slightly over sharpened, but that is just post stuff.</td>', 'I like the pose and a terrific smile. Interesting choice in color for your duo tone. Gives the image more of a fun happy vibe which is expressed in the emotion of the individual. Might be slightly over sharpened, but that is just post stuff.', '2007-11-15 22:03:56.000000', NULL, 1),
(4250653, 611748, 62318, '<td valign="top">Interesting scene. Lighting looks a bit harsh for me. However, the scene works really well. I like the outstretched monkey''s arm and the other more compact.</td>', 'Interesting scene. Lighting looks a bit harsh for me. However, the scene works really well. I like the outstretched monkey''s arm and the other more compact.', '2007-11-15 22:05:07.000000', NULL, 1),
(4250657, 611397, 62318, '<td valign="top">Nice curving road scene. I like that you brought the clouds out in post. I like the general contrast here, though you can definitely see where you tried to dodge/burn a little. I like the textures.</td>', 'Nice curving road scene. I like that you brought the clouds out in post. I like the general contrast here, though you can definitely see where you tried to dodge/burn a little. I like the textures.', '2007-11-15 22:06:23.000000', NULL, 1),
(4250659, 611205, 62318, '<td valign="top">Usually I am not big into re-enactments because usually the history has already been recorded. However, this is a very nice one. I like the catch of gunfire. They way the flag moves across the frame. I even light the individual lying/dying body on the left.</td>', 'Usually I am not big into re-enactments because usually the history has already been recorded. However, this is a very nice one. I like the catch of gunfire. They way the flag moves across the frame. I even light the individual lying/dying body on the left.', '2007-11-15 22:08:02.000000', NULL, 1),
(4250663, 611746, 62318, '<td valign="top">Cool pic. Nuff said.</td>', 'Cool pic. Nuff said.', '2007-11-15 22:09:30.000000', NULL, 1),
(4250671, 612246, 48697, '<td valign="top">cool shot and well composed. I''m not a fan of the inner shadow used though.</td>', 'cool shot and well composed. I''m not a fan of the inner shadow used though.', '2007-11-15 22:18:09.000000', NULL, 1),
(4250673, 610930, 48697, '<td valign="top">This shot looks a bit oof or blurry.</td>', 'This shot looks a bit oof or blurry.', '2007-11-15 22:19:55.000000', NULL, 1),
(4250674, 610677, 48697, '<td valign="top">The forehead and noselooks to have some blownout highlights and the picture seems to be a biy oof.</td>', 'The forehead and noselooks to have some blownout highlights and the picture seems to be a biy oof.', '2007-11-15 22:21:35.000000', NULL, 1),
(4250677, 611557, 48697, '<td valign="top">Very funny how this dragonfly shot has that old time singer feel.  Nicely composed and the lighting is great.  This looks great in b&amp;w, well done!</td>', 'Very funny how this dragonfly shot has that old time singer feel.  Nicely composed and the lighting is great.  This looks great in b&w, well done!', '2007-11-15 22:23:47.000000', NULL, 1),
(4250679, 609377, 48697, '<td valign="top">Cool shot and the tone really enchances the shot. I feel that the composition might have benifited if the top of the lighthouse were not cropped.</td>', 'Cool shot and the tone really enchances the shot. I feel that the composition might have benifited if the top of the lighthouse were not cropped.', '2007-11-15 22:25:27.000000', NULL, 1),
(4250686, 610205, 48697, '<td valign="top">I feel this shot is hurt by motion blur, a reflection of the window that it was taken through and excessive noise/grain.</td>', 'I feel this shot is hurt by motion blur, a reflection of the window that it was taken through and excessive noise/grain.', '2007-11-15 22:29:09.000000', NULL, 1),
(4250687, 609593, 48697, '<td valign="top">The tone really adds to this shot and I love the composition, nicely done!</td>', 'The tone really adds to this shot and I love the composition, nicely done!', '2007-11-15 22:29:55.000000', NULL, 1),
(4250690, 610931, 48697, '<td valign="top">Nice tone and a great subject. I feel that the lower part of the frame could be cropped out.</td>', 'Nice tone and a great subject. I feel that the lower part of the frame could be cropped out.', '2007-11-15 22:31:08.000000', NULL, 1),
(4250703, 611833, 48697, '<td valign="top">Lots going on in this shot but it seesm to work with the perspective and composition used,</td>', 'Lots going on in this shot but it seesm to work with the perspective and composition used,', '2007-11-15 22:39:18.000000', NULL, 1),
(4250725, 610760, 62318, '<td valign="top">Unfortunately I can''t vote on this image. Hope it is doing well for you!</td>', 'Unfortunately I can''t vote on this image. Hope it is doing well for you!', '2007-11-15 23:00:43.000000', NULL, 1),
(4250729, 610926, 62318, '<td valign="top">Very cool tree. Amazing scene. I think it is just a little drab/flat, but otherwise I love it. Still garners a high rating.</td>', 'Very cool tree. Amazing scene. I think it is just a little drab/flat, but otherwise I love it. Still garners a high rating.', '2007-11-15 23:02:16.000000', NULL, 1),
(4250899, 610143, 3145, '<td valign="top">Nice use of lighting , good contrast, this photo has an interesting feel to it.</td>', 'Nice use of lighting , good contrast, this photo has an interesting feel to it.', '2007-11-16 01:45:40.000000', NULL, 1),
(4250900, 610934, 3145, '<td valign="top">Good contrast</td>', 'Good contrast', '2007-11-16 01:46:23.000000', NULL, 1),
(4250904, 610765, 3145, '<td valign="top">The top and bottom seem unbalanced, brighter on the bottom than on the top, it draws the eyes up to the steeple and the gray sky</td>', 'The top and bottom seem unbalanced, brighter on the bottom than on the top, it draws the eyes up to the steeple and the gray sky', '2007-11-16 01:47:58.000000', NULL, 1),
