(4251516, 611435, 84668, '<td valign="top">I love it. 10.</td>', 'I love it. 10.', '2007-11-16 10:41:19.000000', NULL, 1),
(4251535, 611619, 66348, '<td valign="top">I really like the idea here, the more I look the more I like. :P I do however wish it was just a shot of the castle. Its a beautiful shot, but distracting IMO with the people.</td>', 'I really like the idea here, the more I look the more I like. :P I do however wish it was just a shot of the castle. Its a beautiful shot, but distracting IMO with the people.', '2007-11-16 10:51:59.000000', NULL, 1),
(4251537, 611694, 66348, '<td valign="top">Beautiful shot. I love the tone, and the smoothness of the water. I really like the composition as well. Great work. 8</td>', 'Beautiful shot. I love the tone, and the smoothness of the water. I really like the composition as well. Great work. 8', '2007-11-16 10:52:38.000000', NULL, 1),
(4251539, 610405, 66348, '<td valign="top">Great capture, with a great expression. There is a slight strange glow around the child though. Maybe burning that down a bit would have helped. But a great shot non the less.</td>', 'Great capture, with a great expression. There is a slight strange glow around the child though. Maybe burning that down a bit would have helped. But a great shot non the less.', '2007-11-16 10:53:28.000000', NULL, 1),
(4251541, 611207, 66348, '<td valign="top">Love the expression you have captured. Almost looks a bit too edited, with that I mean the child almost looks like a painting. If that is what you were going for you nailed it. I love the eyes, and the slight blown out nose doesn''t harm the shot. Great composition and use of negative space. It tells quite a story in those eyes. Nice work. 8</td>', 'Love the expression you have captured. Almost looks a bit too edited, with that I mean the child almost looks like a painting. If that is what you were going for you nailed it. I love the eyes, and the slight blown out nose doesn''t harm the shot. Great composition and use of negative space. It tells quite a story in those eyes. Nice work. 8', '2007-11-16 10:54:51.000000', NULL, 1),
(4251542, 611341, 66348, '<td valign="top">Almost appears like a pencil sketch. Editing is different but I like different. And the tone works very nice with this church. Well done. 7</td>', 'Almost appears like a pencil sketch. Editing is different but I like different. And the tone works very nice with this church. Well done. 7', '2007-11-16 10:55:31.000000', NULL, 1),
(4251545, 609237, 66348, '<td valign="top">Nice composition and idea. Different style, but I like different. Nice tone with really nice B&amp;W conversion. Nice job.</td>', 'Nice composition and idea. Different style, but I like different. Nice tone with really nice B&W conversion. Nice job.', '2007-11-16 10:56:36.000000', NULL, 1),
(4251552, 610877, 66348, '<td valign="top">I really like the rays you have in this shot. I think the flare look really works. However the ground seems to be lacking contrast. Perhaps a layer with a boost of contrast or some dodging and burning would have helped IMO. Great shot non the less.</td>', 'I really like the rays you have in this shot. I think the flare look really works. However the ground seems to be lacking contrast. Perhaps a layer with a boost of contrast or some dodging and burning would have helped IMO. Great shot non the less.', '2007-11-16 11:00:18.000000', NULL, 1),
(4251556, 611576, 66348, '<td valign="top">Very nice composition. I like how the road leads up to the couple. Great tone and setup. Wedding shots don''t do that great here unfortunately but I hope this is up there. Its one of the better ones. Nice work.</td>', 'Very nice composition. I like how the road leads up to the couple. Great tone and setup. Wedding shots don''t do that great here unfortunately but I hope this is up there. Its one of the better ones. Nice work.', '2007-11-16 11:01:25.000000', NULL, 1),
(4251559, 611089, 66348, '<td valign="top">Great capture. I recently captured a shot like this so I know how difficult it is, unless you got a massive zoom that is. :) I really like your composition and the tone you chose. Well done. 8</td>', 'Great capture. I recently captured a shot like this so I know how difficult it is, unless you got a massive zoom that is. :) I really like your composition and the tone you chose. Well done. 8', '2007-11-16 11:02:16.000000', NULL, 1),
(4251561, 611401, 66348, '<td valign="top">Nicely captured. Love the B&amp;W. Composition works well also. Nice job.</td>', 'Nicely captured. Love the B&W. Composition works well also. Nice job.', '2007-11-16 11:02:52.000000', NULL, 1),
(4251564, 611435, 66348, '<td valign="top">Great capture. The sharpness and clarity are right on, and I love the tone you chose. Composition is sweet as well. Great work. 8</td>', 'Great capture. The sharpness and clarity are right on, and I love the tone you chose. Composition is sweet as well. Great work. 8', '2007-11-16 11:03:40.000000', NULL, 1),
(4251568, 611473, 66348, '<td valign="top">Beautiful shot. Would have liked to see more of the building, but the composition you chose works nice as well. Great tone, and sharpness and clarity are right on.</td>', 'Beautiful shot. Would have liked to see more of the building, but the composition you chose works nice as well. Great tone, and sharpness and clarity are right on.', '2007-11-16 11:05:28.000000', NULL, 1),
(4251569, 611784, 66348, '<td valign="top">Nice composition and angle. I like the lighting and tone you chose as well. Very classy. Nice job.</td>', 'Nice composition and angle. I like the lighting and tone you chose as well. Very classy. Nice job.', '2007-11-16 11:06:20.000000', NULL, 1),
(4251571, 610543, 66348, '<td valign="top">Yeah this would have worked perfect for topless. Great tone, and composition.</td>', 'Yeah this would have worked perfect for topless. Great tone, and composition.', '2007-11-16 11:06:54.000000', NULL, 1),
(4251572, 611557, 66348, '<td valign="top">LOL this is great. Like a scene from a Bug movie. Great composition and tone. A bit blown on top of the dragonfly, but it was probably difficult with the boost of contrast, but its just the right amount of contrast. Great shot. 8</td>', 'LOL this is great. Like a scene from a Bug movie. Great composition and tone. A bit blown on top of the dragonfly, but it was probably difficult with the boost of contrast, but its just the right amount of contrast. Great shot. 8', '2007-11-16 11:08:10.000000', NULL, 1),
(4251573, 610651, 66348, '<td valign="top">I really like the look to your shot. Your editing is sweet on this one. Nice composition and the movement works well. Nice work.</td>', 'I really like the look to your shot. Your editing is sweet on this one. Nice composition and the movement works well. Nice work.', '2007-11-16 11:09:01.000000', NULL, 1),
(4251574, 610809, 66348, '<td valign="top">Great tone and composition. I really like your subject, but its a bummer about the blown roof. But I think you did well with how much sun it looks to have in this shot. Sharpness and clarity are also right on. Nice job.</td>', 'Great tone and composition. I really like your subject, but its a bummer about the blown roof. But I think you did well with how much sun it looks to have in this shot. Sharpness and clarity are also right on. Nice job.', '2007-11-16 11:10:03.000000', NULL, 1),
