(4253123, 609696, 33672, '<td valign="top">What a couple of lucky dogs! Beautiful Beautiful place! Nice tones.</td>', 'What a couple of lucky dogs! Beautiful Beautiful place! Nice tones.', '2007-11-16 22:43:14.000000', NULL, 1),
(4253124, 610673, 33672, '<td valign="top">Very smooth. Nice clean photo.</td>', 'Very smooth. Nice clean photo.', '2007-11-16 22:43:40.000000', NULL, 1),
(4253125, 611595, 58272, '<td valign="top">I love these places. Really makes me want to return to Japan.</td>', 'I love these places. Really makes me want to return to Japan.', '2007-11-16 22:44:27.000000', NULL, 1),
(4253129, 609809, 33672, '<td valign="top">Nice work! Great tones and comp.</td>', 'Nice work! Great tones and comp.', '2007-11-16 22:45:19.000000', NULL, 1),
(4253131, 609317, 58272, '<td valign="top">The background is very busy and for me makes this image feel a little cluttered. Perhaps a different DOF?</td>', 'The background is very busy and for me makes this image feel a little cluttered. Perhaps a different DOF?', '2007-11-16 22:46:31.000000', NULL, 1),
(4253135, 611704, 33672, '<td valign="top">Great work! NIce POV and tones.</td>', 'Great work! NIce POV and tones.', '2007-11-16 22:48:49.000000', NULL, 1),
(4253137, 610939, 58272, '<td valign="top">Something about this statue creeps me out. The compotition here feels a bit awkward. The statue is slightly off center but not enough so to take advantage of the rule of thirds. I''m a master for breaking the rules myself but I think this would benefit from either being completely centered or further to the right.</td>', 'Something about this statue creeps me out. The compotition here feels a bit awkward. The statue is slightly off center but not enough so to take advantage of the rule of thirds. I''m a master for breaking the rules myself but I think this would benefit from either being completely centered or further to the right.', '2007-11-16 22:49:50.000000', NULL, 1),
(4253139, 611406, 58272, '<td valign="top">This is very serene. I think it needs something extra in the composition to give it a bit more interest.</td>', 'This is very serene. I think it needs something extra in the composition to give it a bit more interest.', '2007-11-16 22:51:06.000000', NULL, 1),
(4253140, 610899, 39850, '<td valign="top">7 - Nice image.  Like the crop and composition.</td>', '7 - Nice image.  Like the crop and composition.', '2007-11-16 22:51:14.000000', NULL, 1),
(4253142, 611626, 58272, '<td valign="top">This is almost abstract. I wonder what it would look like with the whole red/yellow/brown Autumn colour scheme.</td>', 'This is almost abstract. I wonder what it would look like with the whole red/yellow/brown Autumn colour scheme.', '2007-11-16 22:52:30.000000', NULL, 1),
(4253145, 611465, 58272, '<td valign="top">Don''t you love co-operative models :)<br/>The collar distracts me here.</td>', 'Don''t you love co-operative models :)The collar distracts me here.', '2007-11-16 22:53:39.000000', NULL, 1),
(4253146, 610325, 39850, '<td valign="top">8 - Nice image.  Fairly minor, but looks like the horizon is out by a whisker.  Undecided whether the image would be even stronger with the corner of that block in, but also ''minor''.  Like your title/concept.  Tonings work well.</td>', '8 - Nice image.  Fairly minor, but looks like the horizon is out by a whisker.  Undecided whether the image would be even stronger with the corner of that block in, but also ''minor''.  Like your title/concept.  Tonings work well.', '2007-11-16 22:53:46.000000', NULL, 1),
(4253149, 611397, 58272, '<td valign="top">Interesting composition. I like the choice of b&amp;w.</td>', 'Interesting composition. I like the choice of b&w.', '2007-11-16 22:54:18.000000', NULL, 1),
(4253150, 611559, 58272, '<td valign="top">This has a great old-time feel about it. I like the textures and the sepia toning.</td>', 'This has a great old-time feel about it. I like the textures and the sepia toning.', '2007-11-16 22:55:14.000000', NULL, 1),
(4253152, 610587, 58272, '<td valign="top">I like the idea of the Eagle(?) landing but this feels a little cluttered.</td>', 'I like the idea of the Eagle(?) landing but this feels a little cluttered.', '2007-11-16 22:57:01.000000', NULL, 1),
