(4253176, 610205, 33379, '<td valign="top">not very sharp.  looks like it was taken through a window or perhaps that is just a reflection at the top?</td>', 'not very sharp.  looks like it was taken through a window or perhaps that is just a reflection at the top?', '2007-11-16 23:16:45.000000', NULL, 1),
(4253179, 610641, 39850, '<td valign="top">7 - Nice unique image.  Bit confused by the pp/effects, will check back pc.</td>', '7 - Nice unique image.  Bit confused by the pp/effects, will check back pc.', '2007-11-16 23:17:46.000000', NULL, 1),
