(4253202, 610871, 33379, '<td valign="top">wow, great capture!</td>', 'wow, great capture!', '2007-11-16 23:28:31.000000', NULL, 1),
(4253203, 611406, 39850, '<td valign="top">Nice image, but looks like some pixelation/something issues.  Blue toning is nice, but I see traces of red, so not sure (for this Challenge).  Fairly minor, but the symmetry seems out, but could be your intent.  The gradient is nice - hopefully natural, ''in image''.</td>', 'Nice image, but looks like some pixelation/something issues.  Blue toning is nice, but I see traces of red, so not sure (for this Challenge).  Fairly minor, but the symmetry seems out, but could be your intent.  The gradient is nice - hopefully natural, ''in image''.', '2007-11-16 23:29:00.000000', NULL, 1),
