(4256044, 611012, 50695, '<td valign="top">Nice, almost Hollywood effect.</td>', 'Nice, almost Hollywood effect.', '2007-11-18 18:42:54.000000', NULL, 1),
(4256045, 611599, 50695, '<td valign="top">What a strange static composition. It''s like Eisenstein couuldn''t get the camera quite where he wanted, but then later decided it was perfect. My ribbons are all used up, but you can have a 10.</td>', 'What a strange static composition. It''s like Eisenstein couuldn''t get the camera quite where he wanted, but then later decided it was perfect. My ribbons are all used up, but you can have a 10.', '2007-11-18 18:44:36.000000', NULL, 1),
(4256050, 611739, 50695, '<td valign="top">I like the disorienting aspect of this. And the new treasures that reward each viewing. Look again, her foot! Look again, a sailor! Look again, land on one side, sea on the other! And then there''s the fact that it''s a great portrait. hubba hubba gotta go 10 with this.</td>', 'I like the disorienting aspect of this. And the new treasures that reward each viewing. Look again, her foot! Look again, a sailor! Look again, land on one side, sea on the other! And then there''s the fact that it''s a great portrait. hubba hubba gotta go 10 with this.', '2007-11-18 18:46:06.000000', NULL, 1),
(4256053, 610143, 50695, '<td valign="top">nice indie grunge look, with a hint of authenticity.</td>', 'nice indie grunge look, with a hint of authenticity.', '2007-11-18 18:47:00.000000', NULL, 1),
