(4256200, 611534, 35804, '<td valign="top">Love this, the tones are just so deep, rich, lush...a lovely quiet image.</td>', 'Love this, the tones are just so deep, rich, lush...a lovely quiet image.', '2007-11-18 19:57:19.000000', NULL, 1),
(4256202, 610765, 1717, '<td valign="top">excellent tone and composition.  love the lines, both intentional and unintentional...like the two streams of water going into the drain that lead my eyes right to the foreground subjects and all the lines of water that carry my eyes down the street and past the background subjects.  really a brilliant image.  very nice work!</td>', 'excellent tone and composition.  love the lines, both intentional and unintentional...like the two streams of water going into the drain that lead my eyes right to the foreground subjects and all the lines of water that carry my eyes down the street and past the background subjects.  really a brilliant image.  very nice work!', '2007-11-18 19:59:27.000000', NULL, 1),
(4256206, 609377, 35804, '<td valign="top">...Longfellow...Henry Wadsworth Longfellow. I do love this shot, the atmosphere is wonderful and are the tones.</td>', '...Longfellow...Henry Wadsworth Longfellow. I do love this shot, the atmosphere is wonderful and are the tones.', '2007-11-18 20:04:53.000000', NULL, 1),
(4256207, 611207, 35804, '<td valign="top">I love this She has such a yearning in here eyes...and thank-you for not neatimaging this to death...I love the texture of the skin...like I can just reach out and touch her face.</td>', 'I love this She has such a yearning in here eyes...and thank-you for not neatimaging this to death...I love the texture of the skin...like I can just reach out and touch her face.', '2007-11-18 20:10:45.000000', NULL, 1),
