(4257614, 610923, 66384, '<td valign="top">Beautiful image, Deb. And the tone is perfect, IMO. There is a lot in this young face to study.</td>', 'Beautiful image, Deb. And the tone is perfect, IMO. There is a lot in this young face to study.', '2007-11-19 09:50:38.000000', NULL, 0),
(4257616, 611725, 73235, '<td valign="top">Congrats Andy for the great shot and the geat score. Top 10% is great.<br/></td>', 'Congrats Andy for the great shot and the geat score. Top 10% is great.', '2007-11-19 09:53:19.000000', NULL, 0),
